css:
/* VIA 對內工作平台 · Dashboard 版面(只有寬度與格線;顏色、字級、燈全部來自 VIA_UI_WorkPlatform_TemplateLock)*/
.wrap.dash{max-width:none;margin:0;padding:10px 14px 30px}
.sysrow{grid-template-columns:repeat(auto-fit,minmax(170px,1fr))}
.grid3{display:grid;grid-template-columns:2fr 1.2fr 1.2fr;gap:10px;align-items:start;margin:0 0 10px}
.grid3>.card{margin:0}
.grid3 .cards{grid-template-columns:repeat(auto-fill,minmax(150px,1fr));margin:0}
.grid3 pre{max-height:260px;overflow:auto}
.mb{display:flex;height:5px;margin-top:4px;border-radius:3px;overflow:hidden}
.mb i{display:block;height:5px;padding:0;border-radius:0;min-width:0;font-size:0;animation:none}
.chip{display:inline-block;border:1px solid var(--line);border-radius:10px;padding:0 6px;font-size:10px;font-weight:400;margin-left:6px}
@media (max-width:1100px){.grid3{grid-template-columns:1fr}}
/* v0101 · 先做這幾件 · 收合區 · 矩陣欄寬(只有寬度與排列;顏色全來自模板鎖冊)*/
.focus table{table-layout:fixed;width:100%}
.focus col.f-l{width:52px}.focus col.f-c{width:64px}.focus col.f-n{width:58px}.focus col.f-s{width:24%}
.focus summary{cursor:pointer}
.focus ul{margin:4px 0 2px 18px;padding:0}
.focus li{margin:1px 0;overflow-wrap:break-word}
.focus .bar{display:flex;gap:8px;align-items:center;flex-wrap:wrap}
.fold>summary{cursor:pointer}
.fold>h2,.fold .cards{margin-top:8px}
section.mxw table{table-layout:fixed;width:100%}
section.mxw col.m-l{width:52px}section.mxw col.m-s{width:64px}section.mxw col.m-b{width:104px}section.mxw col.m-i{width:26%}
section.mxw col.m-v{width:120px}section.mxw col.m-t{width:150px}section.mxw col.m-c{width:58px}section.mxw col.m-d{width:84px}
section.mxw td,section.mxw td.n{white-space:normal;overflow-wrap:break-word;word-break:normal}
section.mxw td.mono{overflow-wrap:anywhere}
